$postModel = new Post();
$categoryModel = new Category();
$allCats = $categoryModel->getAll();
$catMap = [];
foreach ($allCats as $c) {
    $catMap[$c['name']] = $c['id'];
}

$count = 0;
foreach ($news_items as $item) {
    $catName = $item['category'];
    if (!isset($catMap[$catName])) {
        $catId = $categoryModel->create([
            'name' => $catName,
            'slug' => slugify($catName),
            'description' => '',
            'display_order' => 0
        ]);
        $catMap[$catName] = $catId;
    }
    $categoryId = $catMap[$catName];
    
    // Check if post already exists
    $existing = $postModel->getBySlug($item['english_slug']);
    if (!$existing) {
        $postData = [
            'title' => $item['headline'],
            'slug' => $item['english_slug'],
            'excerpt' => $item['excerpt'],
            'content' => $item['details'],
            'category_id' => $categoryId,
            'author_id' => 1,
            'status' => 'published',
            'is_breaking' => 0,
            'is_featured' => 0,
            'is_trending' => 0,
            'seo_title' => $item['seo_title'],
            'meta_description' => $item['meta_description'],
            'focus_keywords' => $item['focus_keywords'],
            'published_at' => date('Y-m-d H:i:s')
        ];
        
        if ($postModel->create($postData)) {
            $count++;
        }
    }
}
echo "<p style='color:green;font-weight:bold;'>Success! Executed {$count} posts. The database has been synced.</p>";
echo "<p>All {$count} posts and categories are now live.</p>";
